import { useCallback, useMemo, useState } from 'react'
import sampleContacts from '../data/sampleContactData.js'

const useContactData = () => {
  const [contacts, setContacts] = useState(sampleContacts)
  const [filters, setFilters] = useState({
    methods: [],
    dateRange: null,
    status: null,
    party: null,
  })

  const filteredContacts = useMemo(() => {
    let result = contacts

    if (filters.methods.length > 0) {
      result = result.filter((c) => filters.methods.includes(c.method))
    }
    if (filters.status) {
      result = result.filter((c) => c.status === filters.status)
    }
    if (filters.party) {
      result = result.filter((c) => c.party === filters.party)
    }
    if (filters.dateRange && filters.dateRange[0] && filters.dateRange[1]) {
      const start = filters.dateRange[0]
      const end = filters.dateRange[1]
      result = result.filter((c) => c.contactDate >= start && c.contactDate <= end)
    }

    return result
  }, [contacts, filters])

  const summaryStats = useMemo(() => {
    const total = filteredContacts.length
    const contacted = filteredContacts.filter((c) => c.status === 'Contacted').length
    const positive = filteredContacts.filter((c) => c.response === 'Supportive' || c.response === 'Leaning').length
    const doorKnocks = filteredContacts.filter((c) => c.method === 'Door Knock').length

    return {
      totalContacts: total,
      contactRate: total > 0 ? ((contacted / total) * 100).toFixed(1) : '0.0',
      positiveResponses: positive,
      doorsKnocked: doorKnocks,
    }
  }, [filteredContacts])

  const methodBreakdown = useMemo(() => {
    const methods = ['Phone', 'Door Knock', 'Text', 'Mail', 'Digital Ad']
    return methods.map((method) => {
      const methodContacts = filteredContacts.filter((c) => c.method === method)
      const total = methodContacts.length
      const successful = methodContacts.filter((c) => c.status === 'Contacted').length
      return {
        method,
        count: total,
        successRate: total > 0 ? ((successful / total) * 100).toFixed(1) : '0.0',
      }
    })
  }, [filteredContacts])

  const partyBreakdown = useMemo(() => {
    const parties = ['Republican', 'Democrat', 'Independent', 'Unregistered']
    return parties.map((party) => {
      const partyContacts = filteredContacts.filter((c) => c.party === party)
      const supportive = partyContacts.filter((c) => c.response === 'Supportive').length
      return {
        party,
        total: partyContacts.length,
        supportive,
        leaning: partyContacts.filter((c) => c.response === 'Leaning').length,
        undecided: partyContacts.filter((c) => c.response === 'Undecided').length,
        opposed: partyContacts.filter((c) => c.response === 'Opposed').length,
      }
    })
  }, [filteredContacts])

  const addContact = useCallback((contactData) => {
    setContacts((prev) => [...prev, { ...contactData, id: String(Date.now()) }])
  }, [])

  const importContacts = useCallback((newContacts) => {
    setContacts((prev) => [...prev, ...newContacts])
  }, [])

  const updateFilters = useCallback((newFilters) => {
    setFilters((prev) => ({ ...prev, ...newFilters }))
  }, [])

  const clearFilters = useCallback(() => {
    setFilters({ methods: [], dateRange: null, status: null, party: null })
  }, [])

  return {
    contacts,
    filteredContacts,
    filters,
    summaryStats,
    methodBreakdown,
    partyBreakdown,
    addContact,
    importContacts,
    updateFilters,
    clearFilters,
  }
}

export default useContactData
