import { ClearOutlined, FilterOutlined } from '@ant-design/icons'
import { Button, Card, Checkbox, DatePicker, Select, Typography } from 'antd'
import React, { memo, useCallback } from 'react'
import styles from './ContactToolPanel.module.css'

const { Title, Text } = Typography
const { RangePicker } = DatePicker

const CONTACT_METHODS = ['Phone', 'Door Knock', 'Text', 'Mail', 'Digital Ad']
const STATUS_OPTIONS = ['Contacted', 'Not Home', 'Refused', 'Moved', 'Deceased']
const PARTY_OPTIONS = ['Republican', 'Democrat', 'Independent', 'Unregistered']

function ContactToolPanel({ filters, updateFilters, clearFilters }) {
  const handleMethodChange = useCallback((checkedValues) => {
    updateFilters({ methods: checkedValues })
  }, [updateFilters])

  const handleStatusChange = useCallback((value) => {
    updateFilters({ status: value || null })
  }, [updateFilters])

  const handlePartyChange = useCallback((value) => {
    updateFilters({ party: value || null })
  }, [updateFilters])

  const handleDateChange = useCallback((dates, dateStrings) => {
    updateFilters({ dateRange: dateStrings[0] ? dateStrings : null })
  }, [updateFilters])

  return (
    <div className={styles.toolPanel}>
      <Title level={5} className={styles.panelTitle}>
        <FilterOutlined /> Filters
      </Title>

      <Card size="small" className={styles.card}>
        <Text strong>Contact Method</Text>
        <Checkbox.Group
          options={CONTACT_METHODS}
          value={filters.methods}
          onChange={handleMethodChange}
          className={styles.checkboxGroup}
        />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Date Range</Text>
        <RangePicker
          onChange={handleDateChange}
          className={styles.fullWidth}
          size="small"
        />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Status</Text>
        <Select
          placeholder="All Statuses"
          value={filters.status}
          onChange={handleStatusChange}
          allowClear
          className={styles.fullWidth}
          options={STATUS_OPTIONS.map((s) => ({ value: s, label: s }))}
        />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Party</Text>
        <Select
          placeholder="All Parties"
          value={filters.party}
          onChange={handlePartyChange}
          allowClear
          className={styles.fullWidth}
          options={PARTY_OPTIONS.map((p) => ({ value: p, label: p }))}
        />
      </Card>

      <div className={styles.buttonGroup}>
        <Button icon={<ClearOutlined />} onClick={clearFilters} block>
          Clear Filters
        </Button>
      </div>
    </div>
  )
}

export default memo(ContactToolPanel)
