import React from 'react'
import useContactData from './hooks/useContactData.jsx'
import ContactToolPanel from './ContactToolPanel.jsx'
import ContactDashboard from './ContactDashboard.jsx'
import styles from './ContactContainer.module.css'

const ContactContainer = () => {
  const contactData = useContactData()

  return (
    <div className={styles.container}>
      <ContactToolPanel
        filters={contactData.filters}
        updateFilters={contactData.updateFilters}
        clearFilters={contactData.clearFilters}
        importContacts={contactData.importContacts}
      />
      <ContactDashboard
        filteredContacts={contactData.filteredContacts}
        summaryStats={contactData.summaryStats}
        methodBreakdown={contactData.methodBreakdown}
        partyBreakdown={contactData.partyBreakdown}
      />
    </div>
  )
}

export default ContactContainer
