import { Card, Col, Progress, Row, Statistic, Table, Tag, Timeline, Typography } from 'antd'
import React, { memo, useMemo } from 'react'
import styles from './ContactDashboard.module.css'

const RESPONSE_COLORS = {
  'Supportive': 'green',
  'Leaning': 'lime',
  'Undecided': 'gold',
  'Opposed': 'red',
}

const STATUS_COLORS = {
  'Contacted': 'green',
  'Not Home': 'orange',
  'Refused': 'red',
  'Moved': 'purple',
  'Deceased': 'default',
}

const contactColumns = [
  { title: 'Name', dataIndex: 'voterName', key: 'voterName', width: 150 },
  { title: 'Party', dataIndex: 'party', key: 'party', width: 110,
    render: (val) => {
      const colors = { Republican: 'red', Democrat: 'blue', Independent: 'purple', Unregistered: 'default' }
      return <Tag color={colors[val]}>{val}</Tag>
    },
  },
  { title: 'Method', dataIndex: 'method', key: 'method', width: 110 },
  { title: 'Status', dataIndex: 'status', key: 'status', width: 110,
    render: (val) => <Tag color={STATUS_COLORS[val]}>{val}</Tag>,
  },
  { title: 'Response', dataIndex: 'response', key: 'response', width: 110,
    render: (val) => val ? <Tag color={RESPONSE_COLORS[val]}>{val}</Tag> : '-',
  },
  { title: 'Date', dataIndex: 'contactDate', key: 'contactDate', width: 110,
    sorter: (a, b) => a.contactDate.localeCompare(b.contactDate),
  },
  { title: 'Volunteer', dataIndex: 'volunteer', key: 'volunteer', width: 120 },
]

function ContactDashboard({ filteredContacts, summaryStats, methodBreakdown, partyBreakdown }) {
  const recentContacts = useMemo(() =>
    [...filteredContacts]
        .sort((a, b) => b.contactDate.localeCompare(a.contactDate))
        .slice(0, 20),
  [filteredContacts])

  const timelineItems = useMemo(() =>
    recentContacts.slice(0, 10).map((c) => ({
      color: STATUS_COLORS[c.status] || 'gray',
      children: `${c.voterName} - ${c.method} (${c.status}) - ${c.contactDate}`,
    })),
  [recentContacts])

  return (
    <div className={styles.dashboard}>
      <Row gutter={[16, 16]}>
        <Col xs={12} sm={6}>
          <Card size="small"><Statistic title="Total Contacts" value={summaryStats.totalContacts} /></Card>
        </Col>
        <Col xs={12} sm={6}>
          <Card size="small"><Statistic title="Contact Rate" value={summaryStats.contactRate} suffix="%" /></Card>
        </Col>
        <Col xs={12} sm={6}>
          <Card size="small"><Statistic title="Positive Responses" value={summaryStats.positiveResponses} valueStyle={{ color: '#3f8600' }} /></Card>
        </Col>
        <Col xs={12} sm={6}>
          <Card size="small"><Statistic title="Doors Knocked" value={summaryStats.doorsKnocked} /></Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} className={styles.sectionRow}>
        <Col xs={24} md={12}>
          <Card title="Contact Method Breakdown" size="small">
            <Table
              dataSource={methodBreakdown.map((m) => ({ ...m, key: m.method }))}
              columns={[
                { title: 'Method', dataIndex: 'method', key: 'method' },
                { title: 'Count', dataIndex: 'count', key: 'count' },
                { title: 'Success Rate', dataIndex: 'successRate', key: 'successRate',
                  render: (val) => <Progress percent={parseFloat(val)} size="small" />,
                },
              ]}
              size="small"
              pagination={false}
            />
          </Card>
        </Col>
        <Col xs={24} md={12}>
          <Card title="Party Breakdown" size="small">
            <Table
              dataSource={partyBreakdown.map((p) => ({ ...p, key: p.party }))}
              columns={[
                { title: 'Party', dataIndex: 'party', key: 'party' },
                { title: 'Total', dataIndex: 'total', key: 'total' },
                { title: 'Supportive', dataIndex: 'supportive', key: 'supportive' },
                { title: 'Leaning', dataIndex: 'leaning', key: 'leaning' },
                { title: 'Undecided', dataIndex: 'undecided', key: 'undecided' },
              ]}
              size="small"
              pagination={false}
            />
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} className={styles.sectionRow}>
        <Col xs={24} md={16}>
          <Card title="Recent Contacts" size="small">
            <Table
              columns={contactColumns}
              dataSource={recentContacts.map((c) => ({ ...c, key: c.id }))}
              size="small"
              pagination={{ pageSize: 10 }}
              scroll={{ x: 800 }}
            />
          </Card>
        </Col>
        <Col xs={24} md={8}>
          <Card title="Activity Feed" size="small" className={styles.timelineCard}>
            <Timeline items={timelineItems} />
          </Card>
        </Col>
      </Row>
    </div>
  )
}

export default memo(ContactDashboard)
